import {parseUPI} from './upi.js';
const $=s=>document.querySelector(s);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=(n,decimals=true)=>'₹'+(Number(n)/100).toLocaleString('en-IN',{minimumFractionDigits:decimals?2:0,maximumFractionDigits:decimals?2:0});
const incoming=t=>['received','topup','refund'].includes(t.type);
const initials=n=>String(n||'PaySmart').trim().split(/\s+/).slice(0,2).map(n=>n[0]).join('').toUpperCase();
const date=(v,options={day:'numeric',month:'short'})=>new Date(v).toLocaleDateString('en-IN',{...options,timeZone:'Asia/Kolkata'});
const clock=v=>new Date(v).toLocaleTimeString('en-IN',{hour:'2-digit',minute:'2-digit',timeZone:'Asia/Kolkata'});
const paths={grid:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',home:'m3 10 9-7 9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1z',send:'m21 3-7 18-4-7-7-4z M10 14 21 3',wallet:'M20 8V5a2 2 0 0 0-2-2H5a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h15V8H5a3 3 0 0 1 0-6 M20 12h-5v5h5 M16 14.5h.1',history:'M3 4v5h5 M3 9a9 9 0 1 1-.2 7 M12 7v5l3 2',chart:'M4 3v17h17 M7 15l4-5 4 3 5-7',chevron:'m9 5 7 7-7 7',down:'m6 9 6 6 6-6',search:'M21 21l-5-5 M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0',sun:'M12 3v-2 M12 23v-2 M3 12H1 M23 12h-2 M5 5 3 3 M21 21l-2-2 M5 19l-2 2 M21 3l-2 2 M17 12a5 5 0 1 1-10 0 5 5 0 0 1 10 0',moon:'M21 13a9 9 0 0 1-10-10 9 9 0 1 0 10 10',bell:'M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9 M10 21h4',shield:'m12 2 8 3v6c0 6-8 11-8 11S4 17 4 11V5z m-4 9 3 3 5-5',help:'M9 8a3 3 0 0 1 6 0c0 2-3 2-3 5 M12 17h.01 M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',settings:'m9 3 1-2h4l1 2 3 2 2 0 2 4-1 2v3l1 2-2 4-3 0-2 2h-4l-1-2-3-2H3l-2-4 1-2v-3L1 9l2-4h3z M16 12a4 4 0 1 1-8 0 4 4 0 0 1 8 0',user:'M16 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0 M4 21v-2a8 8 0 0 1 16 0v2','arrow-up-right':'M5 19 19 5 M5 5h14v14','arrow-down-left':'M19 5 5 19 M5 5v14h14',plus:'M12 5v14 M5 12h14',scan:'M3 8V3h5 M16 3h5v5 M21 16v5h-5 M8 21H3v-5 M7 7h3v3H7z M14 7h3v3h-3z M7 14h3v3H7z M14 14h3v3h-3z',bank:'m2 8 10-6 10 6z M3 21h18 M5 10v8 M10 10v8 M14 10v8 M19 10v8',phone:'M7 2h10a2 2 0 0 1 2 2v16a2 2 0 0 1-2 2H7a2 2 0 0 1-2-2V4a2 2 0 0 1 2-2 M10 18h4 M10 5h4',bill:'M6 2h12v20l-3-2-3 2-3-2-3 2z M9 7h6 M9 11h6 M9 15h3',shop:'M3 9h18l-2-6H5z M4 9v12h16V9 M9 21v-7h6v7 M2 9c0 4 5 4 5 0 0 4 5 4 5 0 0 4 5 4 5 0 0 4 5 4 5 0',gift:'M3 9h18v5H3z M5 14v7h14v-7 M12 9v12 M12 9C5 9 5 2 8 3c3 0 4 6 4 6s1-6 4-6c3-1 3 6-4 6',download:'M12 3v12 m-5-5 5 5 5-5 M4 17v4h16v-4',eye:'M2 12s4-7 10-7 10 7 10 7-4 7-10 7S2 12 2 12 M15 12a3 3 0 1 1-6 0 3 3 0 0 1 6 0',copy:'M9 9h12v12H9z M5 15H3V3h12v2',check:'m5 12 4 4L19 6',close:'m6 6 12 12 M6 18 18 6',lock:'M5 10h14v11H5z M8 10V6a4 4 0 0 1 8 0v4 M12 15v2',logout:'M9 3H3v18h6 M10 12h11 m-4-4 4 4-4 4',camera:'M3 7h4l2-4h6l2 4h4v14H3z M16 13a4 4 0 1 1-8 0 4 4 0 0 1 8 0',mail:'M3 4h18v16H3z m0 1 9 8 9-8',refresh:'M20 7V2 M20 7h-5 M4 17v5 M4 17h5 M20 7a9 9 0 0 0-16 1 M4 17a9 9 0 0 0 16-1'};
const icon=n=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[n]||paths.wallet}"/></svg>`;
function hydrate(root=document){root.querySelectorAll('[data-icon]').forEach(el=>el.innerHTML=icon(el.dataset.icon))}
const btn=(text,action,style='secondary',ico='')=>`<button class="button ${style}" data-action="${action}">${ico?icon(ico):''}${text}</button>`;
let state=null,user=null,route='home',historyFilter='all',search='',period=7,hideBalance=false,toastTimer,cameraStream,scanTimer;
const modal=$('#modal');
let theme;try{theme=localStorage.getItem('paysmart-theme')||'dark'}catch{theme='dark'}
document.documentElement.dataset.theme=theme;
function notify(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),4200)}
function closeModal(){if(cameraStream)cameraStream.getTracks().forEach(t=>t.stop());cameraStream=null;clearInterval(scanTimer);scanTimer=null;modal.close()}
function openModal(html){closeModal();$('#modal-body').innerHTML=html;hydrate(modal);modal.showModal()}
$('.modal-close').onclick=closeModal;modal.addEventListener('cancel',()=>{if(cameraStream)cameraStream.getTracks().forEach(t=>t.stop());clearInterval(scanTimer)});modal.addEventListener('click',e=>{if(e.target===modal)closeModal()});
async function request(path,body){const response=await fetch(path,{method:body===undefined?'GET':'POST',credentials:'same-origin',headers:body===undefined?{}:{'Content-Type':'application/json'},...(body===undefined?{}:{body:JSON.stringify(body)})});let result;try{result=await response.json()}catch{throw Error('The backend could not be reached. Please try again.')}if(!response.ok){const error=Error(result.error||'Please sign in to continue.');error.status=response.status;throw error}return result}
function setIdentity(){document.querySelectorAll('[data-profile-name]').forEach(n=>n.textContent=state?.profile.name||user?.name||'Your account');document.querySelectorAll('[data-initials]').forEach(n=>n.textContent=initials(state?.profile.name||user?.name));$('#tx-count').textContent=state?.transactions.length||0;$('#theme-toggle').innerHTML=icon(theme==='dark'?'sun':'moon')}
function shellAuth(show){document.body.classList.toggle('auth-mode',show);$('#auth-root')?.remove()}
function showAuth(mode='login',message=''){
 closeModal();shellAuth(true);const registering=mode==='register';
 const root=document.createElement('div');root.id='auth-root';root.innerHTML=`<div class="auth-showcase"><a href="#login" class="brand"><span class="brand-symbol">p<span>↗</span></span>PaySmart<span class="brand-dot">.</span></a><div class="auth-story"><div class="eyebrow">BUILT FOR YOUR EVERYDAY</div><h1>A smarter kind<br>of <span>money.</span></h1><p>From your morning chai to your next big plan.<br>Make every rupee feel a little more in control.</p><div class="auth-card"><div class="wallet-top"><span>${icon('wallet')} PaySmart wallet</span><b class="upi-word">UP<span>❯</span><span>❯</span></b></div><div class="auth-card-balance">₹28,450<span>.60</span></div><small>YOUR POSSIBILITIES, MULTIPLIED.</small><div class="auth-card-bottom"><span>ARJUN KUMAR</span><span>•••• 4829</span></div></div><div class="auth-floating">${icon('check')}<div>Everyday, simplified.<small>One place for all your payments.</small></div></div><div class="auth-benefits"><span>${icon('shield')} Protected sessions</span><span>${icon('scan')} UPI app handoff</span><span>${icon('chart')} Clearer insights</span></div></div><small class="auth-showcase-foot">Made for India. Made for everyday. 🇮🇳</small></div><div class="auth-form-side"><a class="auth-mobile-brand brand" href="#login"><span class="brand-symbol">p<span>↗</span></span>PaySmart<span class="brand-dot">.</span></a><div class="auth-form-wrap"><div class="eyebrow">${registering?'YOUR NEXT CHAPTER STARTS HERE':'GOOD TO HAVE YOU BACK'}</div><h2>${registering?'Make room for smarter.':'Welcome back.'}</h2><p>${registering?'Create your account. Give your money a little direction.':'Sign in to your everyday money companion.'}</p><div class="auth-tabs"><button class="${!registering?'active':''}" data-auth-mode="login">Sign in</button><button class="${registering?'active':''}" data-auth-mode="register">Create account</button></div><form id="auth-form">${registering?'<label class="field" for="auth-name">Full name</label><input class="text-input" id="auth-name" name="name" autocomplete="name" maxlength="80" required placeholder="Your full name">':''}<label class="field" for="auth-email">Email address</label><input class="text-input" id="auth-email" name="email" type="email" autocomplete="email" maxlength="254" required placeholder="you@example.com"><div class="auth-password-label"><label class="field" for="auth-password">Password</label><button type="button" id="toggle-password" aria-label="Show password">${icon('eye')}</button></div><input class="text-input" id="auth-password" name="password" type="password" autocomplete="${registering?'new-password':'current-password'}" minlength="${registering?12:1}" maxlength="128" required placeholder="${registering?'At least 12 characters':'Enter your password'}">${registering?'<p class="field-note">Use a unique password with at least 12 characters.</p>':''}<div class="auth-form-meta"><span>${icon('lock')} Your password is encrypted in transit and hashed.</span>${!registering?'<button type="button" data-action="recovery">Need help?</button>':''}</div><p class="form-error" role="alert">${esc(message)}</p><button type="submit" class="button primary modal-submit">${registering?'Create your account':'Sign in to PaySmart'} ${icon('arrow-up-right')}</button></form><div class="auth-disclaimer">${icon('shield')}<p>Your account includes a sandbox wallet with simulated funds. Real UPI payments are authorized in your installed UPI app.</p></div><div class="auth-switch-note">${registering?'Already part of PaySmart?':'New around here?'} <button data-auth-mode="${registering?'login':'register'}">${registering?'Sign in':'Create an account'}</button></div></div><div class="auth-footer"><span>© ${new Date().getFullYear()} PaySmart</span><button data-action="privacy">Privacy & security ↗</button></div></div>`;document.body.append(root);hydrate(root);window.history.replaceState(null,'','#'+mode);
 root.querySelectorAll('[data-auth-mode]').forEach(b=>b.onclick=()=>showAuth(b.dataset.authMode));$('#toggle-password').onclick=()=>{const input=$('#auth-password');input.type=input.type==='password'?'text':'password';$('#toggle-password').setAttribute('aria-label',input.type==='password'?'Show password':'Hide password')};
 $('#auth-form').onsubmit=async e=>{e.preventDefault();const form=e.currentTarget,submit=form.querySelector('[type=submit]');submit.disabled=true;form.querySelector('.form-error').textContent='';const values=Object.fromEntries(new FormData(form));try{const result=await request('/api/auth/'+mode,values);user=result.user;await loadState();shellAuth(false);navigate('home');notify(registering?'Your PaySmart account is ready.':'Welcome back to PaySmart.')}catch(error){form.querySelector('.form-error').textContent=error.message;submit.disabled=false}};
}
function heading(title,subtitle,actions='',eyebrow='YOUR PERSONAL MONEY SPACE'){return `<div class="page-heading ${route==='home'?'home-heading':''}"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${subtitle}</p></div><div class="heading-actions">${actions}</div></div>`}
function balanceCard(){const [whole,fraction]=money(state.balance).split('.');return `<div class="wallet-card"><div class="wallet-top"><span>${icon('wallet')} Total wallet balance <button class="icon-button" data-action="balance" aria-label="Toggle balance visibility">${icon('eye')}</button></span><b class="upi-word">UP<span>❯</span><span>❯</span></b></div><div class="wallet-value">${hideBalance?'₹ ••••••':whole+'<span>.'+fraction+'</span>'}</div><div class="wallet-upi">${esc(state.profile.upi)} <button data-action="copy-wallet" aria-label="Copy sandbox wallet ID">${icon('copy')}</button></div><div class="wallet-actions"><button data-action="add">${icon('plus')} Add money</button><button data-action="transfer">${icon('send')} Send money</button></div><div class="wallet-card-foot"><span>PERSONAL · SANDBOX FUNDS</span><b>paysmart.</b></div></div><div class="linked-bank"><span class="bank-icon">${icon('bank')}</span><div><b>State Bank of India <span style="color:var(--muted)">•• 4829</span></b><small>Simulated bank source · no real account linked</small></div><span>${icon('shield')} Demo</span></div>`}
const paymentOptions=[['scan','scan','Scan & pay'],['upi','send','To UPI ID'],['transfer','user','To a wallet'],['bank','bank','Bank transfer'],['mobile','phone','Mobile recharge'],['bill','bill','Pay bills'],['receive','scan','Receive money'],['merchants','shop','Businesses']];
function quickPayments(){return `<section class="payment-section"><div class="section-title"><h2>Pay anyone. For anything.</h2><button class="text-button" data-route="payments">All payments ${icon('arrow-up-right')}</button></div><div class="payment-grid">${paymentOptions.map(([action,i,label])=>`<button class="payment-option" data-action="${action}"><span>${icon(i)}</span>${label}</button>`).join('')}</div></section>`}
function people(){return `<section class="people-section"><div class="people-intro"><h3>Your people</h3><small>Good company. Easy payments.</small></div><div class="people-list"><button class="person" data-recipient="priya@paysmart"><span class="person-avatar">PS</span>Priya</button><button class="person" data-recipient="rahul@paysmart"><span class="person-avatar">RV</span>Rahul</button><button class="person" data-action="upi"><span class="person-avatar">UPI</span>Pay anyone</button><button class="person" data-action="upi"><span class="person-avatar add-person">${icon('plus')}</span>New</button><div class="people-divider"></div><button class="person merchant-person" data-merchant="Swiggy"><span class="person-avatar">S</span>Swiggy</button><button class="person merchant-person" data-merchant="Starbucks"><span class="person-avatar">★</span>Starbucks</button><div class="people-note">${icon('shield')}Sandbox contacts.<br>Real possibilities.</div></div></section>`}
function istMidnight(){return Math.floor((Date.now()+19800000)/86400000)*86400000-19800000}
function periodTransactions(){const cutoff=istMidnight()-(period-1)*86400000;return state.transactions.filter(t=>new Date(t.date).getTime()>=cutoff&&new Date(t.date).getTime()<=Date.now())}
function spendingData(){const categories=[['Food & dining','#d3f87a',0],['Shopping','#94a8ed',0],['Bills & recharges','#bca6e8',0],['Transfers & others','#e9b58e',0]];for(const t of periodTransactions()){if(incoming(t))continue;let c=t.type==='transfer'?3:['recharge','bill'].includes(t.type)?2:['Swiggy','Starbucks','Zomato'].includes(t.name)?0:t.type==='merchant'?1:3;categories[c][2]+=t.amount}return categories}
function spendingPanel(){const cats=spendingData(),total=cats.reduce((n,c)=>n+c[2],0);let cumulative=0;const gradient=total?'conic-gradient('+cats.filter(c=>c[2]).map(c=>{const start=cumulative;cumulative+=100*c[2]/total;return `${c[1]} ${start}% ${cumulative}%`}).join(',')+')':'var(--line)';return `<section class="panel spending-panel"><div class="panel-heading"><h2>Where it went</h2><span class="eyebrow" style="font-size:8px;letter-spacing:.5px">LAST ${period} DAYS</span></div><div class="donut-wrap"><div class="donut" style="--donut:${gradient}"><div class="donut-inner"><small>Total spent</small><b>${money(total,false)}</b></div></div></div>${cats.map(([name,color,amount])=>`<div class="category-row"><span><i style="background:${color}"></i>${name}</span><b>${total?Math.round(amount/total*100):0}%</b></div>`).join('')}<div class="spending-foot"><button class="text-button" data-route="reports">Know your money better ${icon('arrow-up-right')}</button></div></section>`}
function activityChart(){const days=[];for(let i=period-1;i>=0;i--){const day=new Date(istMidnight()-i*86400000+43200000);const key=date(day,{day:'2-digit',month:'2-digit',year:'numeric'});days.push({date:day,key,sent:0,received:0})}for(const t of state.transactions){const day=days.find(d=>d.key===date(t.date,{day:'2-digit',month:'2-digit',year:'numeric'}));if(day)day[incoming(t)?'received':'sent']+=t.amount}const max=Math.max(10000,...days.flatMap(d=>[d.sent,d.received]));const plot=kind=>days.map((d,i)=>`${i?'L':'M'} ${45+i*(515/(period-1))} ${151-d[kind]/max*118}`).join(' ');let labels='';for(let i=0;i<days.length;i++){if(period===30&&i%5!==0&&i!==29)continue;labels+=`<text x="${45+i*515/(period-1)}" y="179" text-anchor="middle">${period===7?date(days[i].date,{weekday:'short'}):date(days[i].date,{day:'numeric',month:'short'})}</text>`}const total=days.reduce((n,d)=>n+d.sent,0);return `<div class="chart-heading"><div class="chart-total">${money(total)}<small>Spent in the last ${period} days</small></div><div class="chart-legend"><span><i class="legend-dot" style="background:#d3f87a"></i>Spent</span><span><i class="legend-dot" style="background:#8ba9ff"></i>Received</span></div></div><svg class="activity-chart" viewBox="0 0 590 190" role="img" aria-label="Outgoing and incoming transaction amounts over the last ${period} days"><defs><linearGradient id="chart-fill" x1="0" x2="0" y1="0" y2="1"><stop stop-color="#d3f87a" stop-opacity=".11"/><stop offset="1" stop-color="#d3f87a" stop-opacity="0"/></linearGradient></defs>${[0,1,2].map(i=>`<line x1="42" x2="568" y1="${33+i*59}" y2="${33+i*59}"/><text x="0" y="${37+i*59}">${money(max*(1-i/2),false)}</text>`).join('')}<path d="${plot('sent')} L560 151 L45 151 Z" fill="url(#chart-fill)"/><path class="chart-line" d="${plot('received')}" stroke="#8ba9ff"/><path class="chart-line" d="${plot('sent')}" stroke="#d3f87a"/>${days.map((d,i)=>`<circle cx="${45+i*515/(period-1)}" cy="${151-d.sent/max*118}" r="3" fill="#d3f87a"><title>${date(d.date)}: spent ${money(d.sent)}, received ${money(d.received)}</title></circle>`).join('')}${labels}</svg>`}
const merchantColors={'Swiggy':['#ef9c5a','#4d2c15','S'],'Amazon India':['#e9d6ab','#4d4026','a'],'Starbucks':['#76b79c','#183e32','★'],'Jio Prepaid':['#91adf1','#2c426e','Jio'],'Zomato':['#e3929a','#652d38','Z'],'BigBasket':['#a7c781','#344d27','b'],'DMart':['#a5c9a8','#315d36','D']};
function txAvatar(t){const [bg,fg,letter]=merchantColors[t.name]||[incoming(t)?'#a4cdb9':'#b8ace2',incoming(t)?'#355443':'#4b3c6b',initials(t.name)];return `<span class="tx-avatar" style="background:${bg};color:${fg}">${esc(letter)}</span>`}
function historyPanel(full=false){return `<section class="panel history-panel"><div class="panel-heading"><div><h2>${full?'Your transactions':'Recent activity'}</h2><p>Every rupee has a story.</p></div>${full?btn('Export CSV','export','ghost','download'):'<button class="text-button" data-route="history">View all '+icon('arrow-up-right')+'</button>'}</div><div class="history-toolbar"><div class="filter-tabs">${[['all','All'],['sent','Sent'],['received','Received'],['refunded','Refunded']].map(([k,label])=>`<button data-filter="${k}" class="${historyFilter===k?'active':''}">${label}</button>`).join('')}</div><div class="history-search">${icon('search')}<input id="history-search" aria-label="Search transactions" placeholder="Search activity" value="${esc(search)}"></div></div><div class="table-scroll"><table class="history-table"><thead><tr><th>NAME / BUSINESS</th><th>DATE & TIME</th><th>AMOUNT</th><th>STATUS</th></tr></thead><tbody id="history-rows"></tbody></table></div><div class="history-foot"><span>${icon('shield')} Protected by a balanced transaction ledger</span><span>Tap a payment for its receipt ↗</span></div>${full?'<div id="external-intents"></div>':''}</section>`}
function renderRows(){const body=$('#history-rows');if(!body)return;let list=state.transactions.filter(t=>(historyFilter==='all'||historyFilter==='received'&&incoming(t)||historyFilter==='sent'&&!incoming(t)||historyFilter==='refunded'&&t.status==='Refunded')&&`${t.name} ${t.id} ${t.type} ${t.handle}`.toLowerCase().includes(search.toLowerCase()));if(route==='home')list=list.slice(0,5);body.innerHTML=list.map(t=>`<tr data-tx="${esc(t.id)}" tabindex="0" role="button" aria-label="View ${esc(t.name)} receipt"><td><div class="tx-person">${txAvatar(t)}<div><b>${esc(t.name)}</b><small>${esc(t.handle)}</small></div></div></td><td class="tx-date">${date(t.date)}<small>${clock(t.date)}</small></td><td class="${incoming(t)?'amount-in':''}">${incoming(t)?'+':'−'} ${money(t.amount)}</td><td><span class="status-pill ${t.status==='Refunded'?'refunded':''}">${esc(t.status)}</span></td></tr>`).join('')||'<tr><td colspan="4"><div class="empty-state">No matching transactions.<br>Your next money story starts here.</div></td></tr>';if($('#external-intents'))$('#external-intents').innerHTML=externalHistory()}
function externalHistory(){return state.intents.length?`<section class="external-list"><h3>External UPI requests</h3><p>Payment links opened in another app. These are unverified and do not affect your sandbox balance.</p>${state.intents.map(t=>`<div class="external-intent"><span class="stat-icon">${icon('send')}</span><div class="intent-meta"><b>${esc(t.name)}</b><small>${date(t.date)} · ${esc(t.id)}</small></div><strong>${money(t.amount)}</strong><span class="status-pill pending">Unverified</span><button class="button ghost" data-intent="${esc(t.id)}">Open ↗</button></div>`).join('')}</section>`:''}
function home(){const recent=periodTransactions(),sent=recent.filter(t=>!incoming(t)).reduce((n,t)=>n+t.amount,0),received=recent.filter(incoming).reduce((n,t)=>n+t.amount,0);return heading(`Namaste, ${esc(state.profile.name.split(' ')[0])} <span class="wave">✦</span>`,'A fresh day. A smarter way to pay.',btn('Download statement','export','secondary','download')+btn('Make a payment','upi','primary','plus'))+`<section class="stats-grid">${[['wallet','Wallet balance',money(state.balance),'Your personal sandbox wallet'],['arrow-down-left','Money received',money(received),`In the last ${period} days`],['arrow-up-right','Money spent',money(sent),`In the last ${period} days`],['history','Transactions',recent.length.toString(),`In the last ${period} days`]].map(([i,title,value,sub])=>`<div class="stat-card"><span class="stat-icon">${icon(i)}</span><div><p>${title}</p><strong>${value}</strong><small>${sub}</small></div></div>`).join('')}</section><div class="dashboard-top"><section class="panel chart-panel"><div class="panel-heading"><div><h2>Your money in motion</h2><p>A clearer picture of your everyday.</p></div><select class="small-select period-select" aria-label="Activity period"><option value="7" ${period===7?'selected':''}>Last 7 days</option><option value="30" ${period===30?'selected':''}>Last 30 days</option></select></div>${activityChart()}</section><div>${balanceCard()}</div></div>${quickPayments()}${people()}<div class="dashboard-bottom">${historyPanel()}<div class="right-column">${spendingPanel()}<section class="rewards-banner"><span class="reward-star">✦</span><div class="eyebrow">LITTLE WINS. EVERY DAY.</div><h3>Good payments.<br>Great possibilities.</h3><p>A little cashback can make an ordinary day a little better.</p><button class="text-button" data-action="rewards">Explore rewards ${icon('arrow-up-right')}</button></section></div></div>`}
function payments(){const options=[['scan','scan','Scan a UPI QR','At the shop, at the café, anywhere.'],['upi','send','Pay a UPI ID','Open your preferred UPI app.'],['transfer','user','Pay a wallet','Instant sandbox transfers to your people.'],['receive','scan','Receive money','Share a QR for your own UPI ID.'],['mobile','phone','Mobile recharge','Keep the conversation going. Sandbox.'],['bill','bill','Bills & utilities','One less thing on your list. Sandbox.']];return heading('Everyday, paid simply.','Your people. Your places. Your preferred way to pay.',btn('Businesses','merchants','secondary','shop'))+`<div class="payment-workspace"><section class="panel full-page-panel"><div class="panel-heading"><h2>How would you like to pay?</h2><span class="upi-word">UP<span>❯</span><span>❯</span></span></div><div class="payment-options-large">${options.map(([a,i,title,sub])=>`<button class="payment-card" data-action="${a}"><span class="stat-icon">${icon(i)}</span><div><b>${title}</b><p>${sub}</p></div><i>${icon('chevron')}</i></button>`).join('')}</div><div class="payment-tip">${icon('shield')}<span>Sandbox payments use simulated funds. Real UPI payments are authorized in your installed UPI app. Confirm the recipient there before paying.</span></div></section><div class="right-column">${balanceCard()}<section class="panel upi-guide"><h3>A familiar way to UPI.</h3>${[['Enter a UPI ID or scan','Review the recipient and amount.'],['Open your installed UPI app','Your bank app handles authorization.'],['Confirm in your bank app','PaySmart marks requests as unverified until a provider confirms them.']].map(([title,sub],i)=>`<div class="guide-step"><span>${i+1}</span><div><b>${title}</b>${sub}</div></div>`).join('')}</section></div></div>`}
function wallets(){const spentToday=state.transactions.filter(t=>!incoming(t)&&date(t.date,{day:'2-digit',month:'2-digit',year:'numeric'})===date(new Date(),{day:'2-digit',month:'2-digit',year:'numeric'})).reduce((n,t)=>n+t.amount,0);return heading('Your money. Your space.','One wallet for a little more everyday.',btn('Add money','add','primary','plus'))+`<div class="wallets-layout"><div>${balanceCard()}<section class="panel full-page-panel wallet-details"><h3 style="font-size:14px">Daily payment limit</h3><div class="limit-track"><span style="width:${Math.min(100,spentToday/100000)}%"></span></div><div class="limit-caption"><span>${money(spentToday)} used today</span><span>₹1,00,000 limit</span></div><div class="detail-row"><span>Currency</span><b>Indian rupee · INR</b></div><div class="detail-row"><span>Wallet type</span><b>Personal · sandbox</b></div><div class="detail-row"><span>Identity verification</span><b>Demo profile · live KYC not connected</b></div></section></div><section class="panel full-page-panel"><div class="panel-heading"><div><h2>Sandbox network</h2><p>Isolated sample accounts for your wallet.</p></div>${icon('wallet')}</div><div class="counterparty-grid" style="margin-top:24px">${state.wallets.filter(w=>w.id!=='self').map(w=>`<div class="counterparty"><b>${esc(w.id.charAt(0).toUpperCase()+w.id.slice(1))}</b><p>${money(w.balance)}</p></div>`).join('')}</div><p class="report-note">Transfers update both wallets together. Every completed operation writes matching debit and credit entries. These sample counterparties are private to your account.</p></section></div>`}
function reports(){const total=periodTransactions().filter(t=>!incoming(t)).reduce((n,t)=>n+t.amount,0),received=periodTransactions().filter(incoming).reduce((n,t)=>n+t.amount,0),balanced=state.journal.reduce((n,j)=>n+j.delta,0)===0;return heading('A little clarity goes a long way.','Your numbers, without the noise.',btn('Export statement','export','secondary','download'))+`<div class="report-stats">${[['Period received',money(received)],['Period spent',money(total)],['Wallet balance',money(state.balance)]].map(([title,value])=>`<div class="panel report-card"><p>${title}</p><h2>${value}</h2></div>`).join('')}</div><div class="report-grid"><div><section class="panel chart-panel" style="display:block"><div class="panel-heading"><h2>Payment activity</h2><select class="small-select period-select" aria-label="Report period"><option value="7" ${period===7?'selected':''}>Last 7 days</option><option value="30" ${period===30?'selected':''}>Last 30 days</option></select></div>${activityChart()}</section><section class="panel full-page-panel" style="margin-top:22px"><div class="panel-heading"><h2>Ledger consistency</h2><span class="status-pill">${balanced?'Balanced':'Needs review'}</span></div><p class="report-note">Every new sandbox payment has matching debit and credit entries, stored in one atomic database update. Opening sample history predates the journal.</p><div class="ledger-list">${state.journal.length?state.journal.slice(-10).reverse().map(j=>`<div class="ledger-entry"><div>${esc(j.wallet)}<br><small>${esc(j.transactionId)}</small></div><b class="${j.delta>0?'amount-in':''}">${j.delta>0?'+':'−'} ${money(Math.abs(j.delta))}</b></div>`).join(''):'<div class="empty-state">Make your first sandbox payment to see the ledger.</div>'}</div></section></div><div>${spendingPanel()}<section class="panel full-page-panel" style="margin-top:22px"><h3 style="font-size:13px">The complete picture</h3><div class="detail-row"><span>Recorded transactions</span><b>${state.transactions.length}</b></div><div class="detail-row"><span>Refunds completed</span><b>${state.transactions.filter(t=>t.type==='refund').length}</b></div><div class="detail-row"><span>External UPI requests</span><b>${state.intents.length}</b></div><p class="report-note">External requests are unverified and excluded from wallet totals. Charts use your recorded transactions in Indian Standard Time.</p></section></div></div>`}
function profile(){return heading('A space that’s yours.','Manage your profile and the ways you get paid.',btn('Sign out','logout','secondary','logout'))+`<div class="profile-layout"><section class="panel full-page-panel"><div class="profile-heading"><span class="profile-avatar">${esc(initials(state.profile.name))}</span><div><h2>${esc(state.profile.name)}</h2><p>${esc(user.email)}</p></div></div><form id="profile-form" class="settings-form"><label class="field" for="display-name">Full name</label><input id="display-name" class="text-input" name="name" value="${esc(state.profile.name)}" required maxlength="80" autocomplete="name"><label class="field" for="receive-upi">Your real UPI ID (optional)</label><input id="receive-upi" class="text-input" name="receiveUpi" value="${esc(state.profile.receiveUpi||'')}" placeholder="yourname@yourbank" maxlength="100" spellcheck="false"><p class="field-note">Used to generate your receive-money QR. Confirm this ID in your bank app. PaySmart cannot verify ownership or existence.</p><div class="form-error" role="alert"></div><button class="button primary" style="margin-top:20px">Save profile ${icon('check')}</button></form></section><section class="panel full-page-panel"><h3 style="font-size:14px">A little peace of mind.</h3><div class="info-list">${[['lock','Your account, protected','Passwords are salted and hashed. Sessions use HttpOnly cookies and can be revoked by signing out.'],['shield','Keep your UPI PIN private','Only enter your PIN in an authorized UPI or bank app. PaySmart never asks for it.'],['wallet','Know your money','Your wallet contains simulated funds. Real UPI links never debit or credit the sandbox.']].map(([i,title,sub])=>`<div class="info-item">${icon(i)}<div><b>${title}</b><p>${sub}</p></div></div>`).join('')}</div><button class="button ghost" style="margin-top:25px;width:100%" data-action="privacy">Privacy & security ${icon('arrow-up-right')}</button></section></div>`}
function merchants(){return heading('Your favourite everyday places.','Registered demo merchants. Payments use sandbox funds.',btn('Pay real merchant UPI','upi','primary','send'))+`<div class="merchant-grid">${Object.keys(merchantColors).filter(n=>n!=='Jio Prepaid').map(n=>`<button class="panel merchant-tile" data-merchant="${n}">${txAvatar({name:n,type:'merchant'})}<b>${n}</b><p>Registered sandbox merchant</p><span class="text-button">Make a payment ${icon('arrow-up-right')}</span></button>`).join('')}</div>`}
function navigate(next,replace=false){if(!state||!user){showAuth('login');return}if(!['home','payments','history','wallets','reports','profile','merchants'].includes(next))next='home';route=next;search='';historyFilter='all';if(!replace)history.pushState(null,'','#'+next);render();window.scrollTo({top:0,behavior:'instant'})}
function render(){if(!state)return;const pages={home,payments,history:()=>heading('Every payment. Every detail.','A clear record of where your money goes.',btn('Make a payment','upi','primary','send'))+historyPanel(true),wallets,reports,profile,merchants};$('#page').innerHTML=pages[route]();$('#breadcrumb').textContent=({home:'Overview',payments:'Payments',history:'Transactions',wallets:'My wallets',reports:'Insights & reports',profile:'Account settings',merchants:'Businesses'})[route];document.querySelectorAll('[data-route]').forEach(b=>b.classList.toggle('active',b.dataset.route===route));setIdentity();hydrate();renderRows();document.querySelectorAll('.period-select').forEach(el=>el.onchange=()=>{period=Number(el.value);render()});if($('#history-search'))$('#history-search').oninput=e=>{search=e.target.value;renderRows()};if($('#profile-form'))$('#profile-form').onsubmit=async e=>{e.preventDefault();const submit=e.currentTarget.querySelector('button');submit.disabled=true;try{const result=await request('/api/profile',Object.fromEntries(new FormData(e.currentTarget)));state=result.state;render();notify('Profile updated. A little more you.')}catch(error){$('#profile-form .form-error').textContent=error.message;submit.disabled=false}}}
async function loadState(){state=await request('/api/state');$('#connection-banner').hidden=true;setIdentity()}
function copy(text){const fallback=()=>openModal(`<h2>Copy this value</h2><input class="text-input" style="margin-top:20px" readonly value="${esc(text)}">`);if(!navigator.clipboard){fallback();return}navigator.clipboard.writeText(text).then(()=>notify('Copied to clipboard.')).catch(fallback)}
function paymentForm(kind='upi',prefill={}){
 const external=kind==='upi';const titles={upi:'Pay a UPI ID.',transfer:'Send a little something.',merchant:'Your everyday, paid.',add:'A little more in your wallet.',mobile:'Keep the conversation going.',bill:'One less thing to do.'};const labels={upi:'Recipient UPI ID',transfer:'PaySmart wallet ID',merchant:'Merchant',add:'Funding source',mobile:'Indian mobile number',bill:'Biller / account reference'};const key=crypto.randomUUID();
 openModal(`<div class="modal-icon">${icon(external?'send':kind==='add'?'plus':kind==='mobile'?'phone':kind==='bill'?'bill':'wallet')}</div><div class="eyebrow">${external?'EXTERNAL UPI · REAL PAYMENT HANDOFF':'PAYSMART · SANDBOX PAYMENT'}</div><h2>${titles[kind]}</h2><p class="modal-description">${external?'Enter a UPI ID, review the details, then authorize in your preferred UPI app.':'Use simulated wallet funds. Available balance: '+money(state.balance)}</p>${['upi','transfer'].includes(kind)?`<div class="modal-switch"><button data-switch="upi" class="${external?'active':''}">Real UPI ID</button><button data-switch="transfer" class="${!external?'active':''}">Sandbox wallet</button></div>`:''}<form id="payment-form"><label class="field" for="pay-recipient">${labels[kind]}</label>${kind==='merchant'?`<select id="pay-recipient" class="text-input" name="name">${Object.keys(merchantColors).filter(n=>n!=='Jio Prepaid').map(n=>`<option ${n===prefill.name?'selected':''}>${n}</option>`).join('')}</select>`:kind==='add'?'<input id="pay-recipient" class="text-input" name="name" value="Demo bank •••• 4829" readonly>':kind==='transfer'?`<select id="pay-recipient" class="text-input" name="name"><option value="priya@paysmart" ${prefill.name==='priya@paysmart'?'selected':''}>Priya Sharma · priya@paysmart</option><option value="rahul@paysmart" ${prefill.name==='rahul@paysmart'?'selected':''}>Rahul Verma · rahul@paysmart</option></select>`:`<input id="pay-recipient" class="text-input" name="name" required maxlength="100" ${kind==='mobile'?'inputmode="numeric" pattern="[6-9][0-9]{9}"':''} placeholder="${external?'recipient@okaxis':kind==='mobile'?'10-digit mobile number':'e.g. BESCOM · account 123456'}" value="${esc(prefill.name||'')}" spellcheck="false">`}${external?`<label class="field" for="payee-name">Recipient name (optional)</label><input id="payee-name" class="text-input" name="payeeName" maxlength="80" placeholder="Recipient name" value="${esc(prefill.payeeName||'')}">`:''}<label class="field" for="pay-amount">Amount in INR</label><div class="amount-input-wrap"><span>₹</span><input id="pay-amount" type="number" name="amount" min="1" max="100000" step="0.01" required inputmode="decimal" placeholder="0.00" value="${esc(prefill.amount||'')}"></div><div class="amount-presets">${[100,500,1000,2000].map(n=>`<button type="button" data-amount="${n}">₹${n.toLocaleString('en-IN')}</button>`).join('')}</div><div class="form-error" role="alert"></div><button type="submit" class="button primary modal-submit">Review payment ${icon('arrow-up-right')}</button></form><p class="modal-footnote">${external?'UPI ID syntax only. Confirm the actual payee in your UPI app.':'Sandbox verification uses code 123456. Never enter a real UPI PIN.'}</p>`);
 modal.querySelectorAll('[data-switch]').forEach(b=>b.onclick=()=>paymentForm(b.dataset.switch));modal.querySelectorAll('[data-amount]').forEach(b=>b.onclick=()=>$('#pay-amount').value=b.dataset.amount);
 $('#payment-form').onsubmit=e=>{e.preventDefault();const values=Object.fromEntries(new FormData(e.currentTarget));const amount=Math.round(Number(values.amount)*100);if(external){try{parseUPI('upi://pay?'+new URLSearchParams({pa:values.name.trim(),am:values.amount,cu:'INR'}))}catch(error){$('.form-error').textContent=error.message;return}}reviewPayment({type:({upi:'upi_intent',transfer:'transfer',merchant:'merchant',add:'topup',mobile:'recharge',bill:'bill'})[kind],name:values.name.trim(),payeeName:values.payeeName||'',amount,key},kind)};
}
function reviewPayment(input,kind){const external=input.type==='upi_intent';openModal(`<div class="eyebrow">ONE LAST LOOK</div><h2>${external?'Ready when you are.':'Looks good?'}</h2><p class="modal-description">${external?'A real payment will be authorized in your bank app.':'Review your sandbox payment before confirming.'}</p><div class="review-recipient">${txAvatar({name:input.payeeName||input.name,type:input.type})}<div><b>${esc(input.payeeName||input.name)}</b><small>${external?esc(input.name):'PaySmart sandbox payment'}</small></div></div><div class="review-amount">${money(input.amount)}</div><div class="method-row">${icon(external?'bank':'wallet')}<div><p>${external?'Installed UPI / bank app':input.type==='topup'?'Simulated linked bank':'PaySmart wallet'}</p><small>${external?'Real money · check your bank balance':'Simulated funds · '+money(state.balance)+' available'}</small></div><span>INR</span></div><form id="confirm-form">${external?'<div class="verification-hint">Verify the payee name and amount in your UPI app. PaySmart cannot confirm payment completion without a verified provider callback.</div>':'<div class="verification-hint">Sandbox verification code: <b>123456</b>. This is not a real OTP or UPI PIN.</div><label class="field" for="verify-code">Sandbox verification code</label><input id="verify-code" class="text-input" name="code" inputmode="numeric" pattern="123456" maxlength="6" required placeholder="123456" autocomplete="off">'}<div class="form-error" role="alert"></div><button class="button primary modal-submit">${external?'Create UPI payment link':'Verify & '+(input.type==='topup'?'add money':input.type==='refund'?'refund':'pay')} ${icon('arrow-up-right')}</button><button type="button" class="button ghost modal-submit" id="edit-payment" style="margin-top:10px">${kind?'Edit details':'Cancel'}</button></form>`);$('#edit-payment').onclick=()=>kind?paymentForm(kind,{...input,amount:input.amount/100}):closeModal();$('#confirm-form').onsubmit=async e=>{e.preventDefault();const form=e.currentTarget,submit=form.querySelector('[type=submit]')||form.querySelector('.primary');submit.disabled=true;form.querySelector('.form-error').textContent='';try{const result=await request(external?'/api/upi-intents':'/api/transactions',{...input,...(!external?{code:new FormData(form).get('code')}:{})});state=result.state;render();if(external)upiResult(result.result);else receipt(result.result.id,true)}catch(error){form.querySelector('.form-error').textContent=error.message;submit.disabled=false}}}
function qr(uri){const code=window.qrcode(0,'M');code.addData(uri);code.make();return code.createSvgTag({cellSize:4,margin:2,scalable:true})}
function upiResult(intent){openModal(`<div class="eyebrow">EXTERNAL UPI REQUEST</div><h2>Your payment link is ready.</h2><div class="review-amount">${money(intent.amount)}</div><div class="qr-surface">${qr(intent.uri)}</div><p class="qr-caption">Scan with your UPI app or open the link on your phone.</p><div class="upi-handoff">${icon('send')}<div><b>${esc(intent.name)}</b><small>${esc(intent.id)}</small></div><span class="status-pill pending">Unverified</span></div><a class="button primary modal-submit" href="${esc(intent.uri)}">Open installed UPI app ${icon('arrow-up-right')}</a><button class="button ghost modal-submit" id="copy-upi-link" style="margin-top:10px">${icon('copy')} Copy payment link</button><p class="modal-footnote">Confirm the recipient in your bank app. No payment is credited to PaySmart based on opening this link. Check final status in your UPI app.</p>`);$('#copy-upi-link').onclick=()=>copy(intent.uri)}
function receipt(id,success=false){const t=state.transactions.find(t=>t.id===id);if(!t)return;openModal(`<div class="receipt-heading"><div class="success-mark">${icon(t.status==='Refunded'?'refresh':'check')}</div><div class="eyebrow">${success?'A LITTLE MOMENT, WELL PAID':'PAYSMART · TRANSACTION RECEIPT'}</div><h2>${money(t.amount)}</h2><p>${incoming(t)?'Received from':'Paid to'} ${esc(t.name)}</p></div>${[['Status',t.status],['Reference',t.id],['Payment type',t.type],['Date & time',date(t.date)+' · '+clock(t.date)],['Payment method','Sandbox wallet'],['Currency','INR · Indian rupee']].map(([label,value])=>`<div class="detail-row"><span>${label}</span><b>${esc(value)}</b></div>`).join('')}${t.type==='merchant'&&t.status==='Completed'?'<button class="button secondary modal-submit" id="refund-payment">'+icon('refresh')+' Refund sandbox payment</button>':''}<button class="button primary modal-submit" id="receipt-done">Done ${icon('check')}</button><p class="modal-footnote">Simulated funds. No real bank or UPI payment was made.</p>`);$('#receipt-done').onclick=closeModal;if($('#refund-payment'))$('#refund-payment').onclick=()=>reviewPayment({type:'refund',name:t.name+' refund',amount:t.amount,key:crypto.randomUUID(),originalId:t.id},null)}
function receiveMoney(){openModal(`<div class="modal-icon">${icon('scan')}</div><div class="eyebrow">YOUR MONEY, COMING YOUR WAY</div><h2>Say it with a QR.</h2><p class="modal-description">Generate a receive-money QR for your own real UPI ID. A UPI app will send funds directly to that account.</p><form id="receive-form"><label class="field" for="receive-id">Your real UPI ID</label><input id="receive-id" class="text-input" name="name" value="${esc(state.profile.receiveUpi||'')}" placeholder="yourname@yourbank" required maxlength="100"><label class="field" for="receive-amount">Amount in INR (optional)</label><input id="receive-amount" class="text-input" name="amount" type="number" min="1" max="100000" step="0.01" placeholder="Let the sender choose"><div class="form-error" role="alert"></div><button class="button primary modal-submit">Generate my QR ${icon('scan')}</button></form><p class="modal-footnote">Enter your own UPI ID from your bank app. PaySmart cannot verify ownership. You never need to enter a UPI PIN to receive money.</p>`);$('#receive-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.currentTarget),name=f.get('name').trim(),amount=f.get('amount');const params={pa:name,pn:state.profile.name,cu:'INR',...(amount?{am:amount}:{})};const uri='upi://pay?'+new URLSearchParams(params);try{parseUPI(uri)}catch(error){$('.form-error').textContent=error.message;return}openModal(`<div class="eyebrow">SCAN. SEND. SIMPLE.</div><h2 style="text-align:center">${esc(state.profile.name)}</h2><div class="qr-surface">${qr(uri)}</div><p class="qr-caption"><b>${esc(name)}</b>${amount?'<br>'+money(Math.round(Number(amount)*100)):''}<br>Scan with any supported UPI app.</p><button class="button primary modal-submit" id="share-receive">${icon('copy')} Copy UPI link</button><button class="button ghost modal-submit" id="save-qr" style="margin-top:10px">${icon('download')} Download QR</button><p class="modal-footnote">Payments go to the UPI account above, not the PaySmart sandbox. Confirm your UPI ID before sharing.</p>`);$('#share-receive').onclick=()=>copy(uri);$('#save-qr').onclick=()=>{const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([qr(uri)],{type:'image/svg+xml'}));a.download='PaySmart-receive-QR.svg';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}}}
async function decodeQR(source){
 if('BarcodeDetector' in window){try{const codes=await new BarcodeDetector({formats:['qr_code']}).detect(source);if(codes[0])return codes[0].rawValue}catch{}}
 if(!window.jsQR)return null;
 const width=source.videoWidth||source.width,height=source.videoHeight||source.height;if(!width||!height)return null;
 const scale=Math.min(1,1400/Math.max(width,height)),canvas=document.createElement('canvas');canvas.width=Math.round(width*scale);canvas.height=Math.round(height*scale);
 const context=canvas.getContext('2d',{willReadFrequently:true});context.drawImage(source,0,0,canvas.width,canvas.height);const pixels=context.getImageData(0,0,canvas.width,canvas.height);
 return window.jsQR(pixels.data,pixels.width,pixels.height,{inversionAttempts:'attemptBoth'})?.data||null;
}
async function scan(){
 openModal(`<div class="eyebrow">POINT. SCAN. PAY.</div><h2>Scan a UPI QR.</h2><p class="modal-description">We’ll show you the recipient and amount before you continue.</p><div class="scanner" id="scanner"><div class="scanner-placeholder">${icon('scan')}<p>Start your camera to scan a UPI QR.</p></div></div><button class="button primary modal-submit" id="start-camera">${icon('camera')} Start camera</button><div class="scan-fallback"><label class="field" for="qr-file">Or upload a QR image</label><input id="qr-file" class="text-input" type="file" accept="image/*"><label class="field" for="upi-link-input">Or paste a UPI payment link</label><textarea class="text-input" id="upi-link-input" rows="2" placeholder="upi://pay?pa=merchant@bank&cu=INR"></textarea><button class="button secondary modal-submit" id="parse-link" style="margin-top:12px">Review payment ${icon('arrow-up-right')}</button></div><div class="form-error" id="scan-error" role="alert"></div><p class="modal-footnote">Camera access needs HTTPS and your permission. You can also upload a QR image or paste a UPI link.</p>`);
 const error=message=>{if($('#scan-error'))$('#scan-error').textContent=message};
 const scanned=value=>{try{const parsed=parseUPI(value);closeModal();paymentForm('upi',parsed)}catch(e){error(e.message)}};
 $('#parse-link').onclick=()=>scanned($('#upi-link-input').value);
 $('#start-camera').onclick=async()=>{
  try{
   if(!navigator.mediaDevices?.getUserMedia)throw Error();
   const stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:{ideal:'environment'}}});
   if(!modal.open||!$('#scanner')){stream.getTracks().forEach(t=>t.stop());return}cameraStream=stream;
   $('#scanner').innerHTML='<video id="qr-video" autoplay muted playsinline></video><div class="scanner-overlay"></div>';
   const video=$('#qr-video');video.srcObject=stream;await video.play();let detecting=false;
   scanTimer=setInterval(async()=>{if(detecting||video.readyState<2)return;detecting=true;try{const code=await decodeQR(video);if(code&&$('#scanner'))scanned(code)}catch{}finally{detecting=false}},450);
   $('#start-camera').hidden=true;
  }catch{if(cameraStream)cameraStream.getTracks().forEach(t=>t.stop());error('Camera access was unavailable. Allow camera access, upload a QR image, or paste a UPI link.')}
 };
 $('#qr-file').onchange=async e=>{
  const file=e.target.files?.[0];if(!file)return;if(file.size>10000000){error('Choose an image smaller than 10 MB.');return}
  let objectUrl;
  try{objectUrl=URL.createObjectURL(file);const image=new Image();image.src=objectUrl;await image.decode();const value=await decodeQR(image);if(!value)throw Error('No QR found. Try a clearer image.');if($('#scanner'))scanned(value)}catch(e){error(e.message)}finally{if(objectUrl)URL.revokeObjectURL(objectUrl)}
 };
}
function exportCSV(){const cells=[['Reference','Name','Type','Amount (INR)','Direction','Status','Date (IST)'],...state.transactions.map(t=>[t.id,t.name,t.type,(t.amount/100).toFixed(2),incoming(t)?'Received':'Sent',t.status,new Date(t.date).toLocaleString('en-IN',{timeZone:'Asia/Kolkata'})])];const csv=cells.map(row=>row.map(v=>'"'+String(v).replace(/^[=+\-@\t\r]/,"'$&").replaceAll('"','""')+'"').join(',')).join('\r\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob(['\uFEFF'+csv],{type:'text/csv;charset=utf-8'}));a.download='PaySmart-statement-'+new Date().toISOString().slice(0,10)+'.csv';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);notify('Your statement is ready.')}
function searchModal(){openModal(`<div class="eyebrow">FIND YOUR MONEY STORY</div><h2>Looking for something?</h2><label class="field" for="global-query">Name, transaction ID or payment type</label><input class="text-input" id="global-query" placeholder="Try Swiggy or a transaction ID"><div id="global-results" style="margin-top:20px"></div>`);const draw=()=>{const q=$('#global-query').value.toLowerCase();$('#global-results').innerHTML=state.transactions.filter(t=>(t.name+' '+t.id+' '+t.type).toLowerCase().includes(q)).slice(0,8).map(t=>`<button data-tx="${esc(t.id)}" class="detail-row" style="width:100%"><span>${esc(t.name)}<small style="display:block;margin-top:5px;font-size:8px">${esc(t.id)}</small></span><b>${money(t.amount)}</b></button>`).join('')||'<div class="empty-state">No matching payments.</div>'};$('#global-query').oninput=draw;draw();$('#global-query').focus()}
const actions={upi:()=>paymentForm('upi'),transfer:()=>paymentForm('transfer'),add:()=>paymentForm('add'),mobile:()=>paymentForm('mobile'),bill:()=>paymentForm('bill'),scan,receive:receiveMoney,balance:()=>{hideBalance=!hideBalance;render()},'copy-wallet':()=>copy(state.profile.upi),merchants:()=>navigate('merchants'),export:exportCSV,search:searchModal,notifications:()=>openModal(`<div class="modal-icon">${icon('bell')}</div><h2>A little peace and quiet.</h2><p class="modal-description">You’re all caught up. Your payment receipts are saved in Transactions.</p><div class="detail-row"><span>Recorded payments</span><b>${state.transactions.length}</b></div><div class="detail-row"><span>Unverified UPI requests</span><b>${state.intents.length}</b></div>`),bank:()=>openModal(`<div class="modal-icon">${icon('bank')}</div><h2>Bank transfers, with clarity.</h2><p class="modal-description">Direct bank transfers need a regulated payment provider. This project has no live bank integration.</p><p class="modal-description">You can send a real payment to a bank-linked UPI ID using an installed UPI app.</p>${btn('Pay a real UPI ID','upi','primary modal-submit','send')}`),rewards:()=>openModal(`<div class="eyebrow">LITTLE WINS. EVERY DAY.</div><h2>A little something to smile about.</h2><p class="modal-description">A preview of PaySmart rewards. These illustrative offers do not credit cashback.</p><div class="rewards-grid"><div class="reward-tile"><span>✦</span><b>Everyday delights</b><p>Up to ₹100 cashback on a first payment. Product preview.</p></div><div class="reward-tile"><span>↗</span><b>Good habits, rewarded</b><p>One place for your bills, payments and spending insights.</p></div></div>`),support:()=>openModal(`<div class="modal-icon">${icon('help')}</div><h2>A little help goes a long way.</h2><p class="modal-description">For sandbox payments, use verification code <b>123456</b>. Send to priya@paysmart or rahul@paysmart, or choose a registered demo merchant.</p><p class="modal-description">For real UPI, enter a real UPI ID or scan a QR. Your UPI app handles payment authorization. Check final payment status there.</p><p class="modal-description">Select any completed sandbox merchant payment in your history to request a full refund.</p>`),privacy:()=>openModal(`<div class="modal-icon">${icon('shield')}</div><h2>Your money deserves clarity.</h2><p class="modal-description">Passwords are salted and hashed with PBKDF2. Sessions use HttpOnly, SameSite cookies. Your wallet records are stored in a database and scoped to your authenticated account.</p><p class="modal-description">Never enter a real OTP, bank password or UPI PIN in PaySmart. Sandbox funds are simulated. Personal UPI IDs are stored only if you save them in your profile or create a payment request.</p><p class="modal-description">This is an educational payment platform, with no live KYC, bank balance access or payment-provider settlement.</p>`),recovery:()=>openModal(`<h2>Let’s get you back in.</h2><p class="modal-description">Password reset emails are not configured for this project. Use the password you chose when registering. Avoid creating accounts with sensitive personal data during testing.</p>`),logout:async()=>{try{await request('/api/auth/logout',{});state=null;user=null;showAuth('login');notify('You’ve been signed out.')}catch(error){notify(error.message)}}};
document.addEventListener('click',e=>{const target=e.target.closest('button,a,tr[data-tx]');if(!target)return;if(target.dataset.route){e.preventDefault();navigate(target.dataset.route)}else if(target.dataset.action){e.preventDefault();if(!user&&!['privacy','recovery','support'].includes(target.dataset.action))return;actions[target.dataset.action]?.()}else if(target.dataset.tx)receipt(target.dataset.tx);else if(target.dataset.recipient)paymentForm('transfer',{name:target.dataset.recipient});else if(target.dataset.merchant)paymentForm('merchant',{name:target.dataset.merchant});else if(target.dataset.intent){const intent=state.intents.find(t=>t.id===target.dataset.intent);if(intent)upiResult(intent)}else if(target.dataset.filter){historyFilter=target.dataset.filter;document.querySelectorAll('[data-filter]').forEach(b=>b.classList.toggle('active',b.dataset.filter===historyFilter));renderRows()}});
document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'&&user){e.preventDefault();searchModal()}if(e.key==='Enter'&&e.target.matches('tr[data-tx]'))receipt(e.target.dataset.tx)});
$('#theme-toggle').onclick=()=>{theme=theme==='dark'?'light':'dark';document.documentElement.dataset.theme=theme;try{localStorage.setItem('paysmart-theme',theme)}catch{}setIdentity()};
window.addEventListener('popstate',()=>{if(!user){showAuth((location.hash?location.hash==='#register':location.pathname==='/register')?'register':'login');return}navigate(location.hash.slice(1),true)});
async function bootstrap(){hydrate();$('#page').innerHTML='<div class="loading-shell"><div><span class="brand-symbol">p↗</span><p>A little smarter is on its way…</p></div></div>';try{const result=await request('/api/auth/me');user=result.user;await loadState();shellAuth(false);navigate(location.hash.slice(1)||'home',true)}catch(error){if(error.status===401){showAuth((location.hash?location.hash==='#register':location.pathname==='/register')?'register':'login')}else{shellAuth(true);showAuth('login',error.message)}}}
bootstrap();
